const rows = $('Sched: Leer última fila').all();
const last = rows.length ? rows[rows.length - 1].json : {};

let copy;
if (choice === '1') copy = last.Copy_Op1;
else if (choice === '2') copy = last.Copy_Op2;
else if (choice === '3') copy = last.Copy_Op3;
else copy = last.Copy_Final || last.Copy_Op1;
copy = String(copy || '').trim();

// carrusel: lista de URLs desde el static data del set
let carouselUrls = '';
if (type === 'carousel' && pend.gid) {
  const set = store['carousel_' + pend.gid] || {};
  carouselUrls = (set.urls || []).join('\n');
  // el static data refleja la edición (HU5: Aplicar edición actualiza copys[n-1]); priorizarlo
  const sc = set.copys && set.copys[Number(choice) - 1];
  if (sc) copy = String(sc).trim();
}

// parse DD/MM HH:MM -> ISO con offset -03:00
function parseFecha(t) {
  const m = t.match(/^(\d{1,2})\/(\d{1,2})\s+(\d{1,2}):(\d{2})$/);
  if (!m) return null;
  const dd = Number(m[1]), MM = Number(m[2]), hh = Number(m[3]), mm = Number(m[4]);
  if (MM < 1 || MM > 12 || dd < 1 || dd > 31 || hh > 23 || mm > 59) return null;
  const year = new Date().getFullYear();
  const iso = year + '-' + String(MM).padStart(2, '0') + '-' + String(dd).padStart(2, '0') + 'T' + String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0') + ':00-03:00';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  return { iso, ms: d.getTime() };
}

const parsed = parseFecha(text);
if (!parsed) return [{ json: { valid: false, chatId, errorMsg: '❌ No entendí la fecha. Mandámela así: DD/MM HH:MM (ej: 05/07 18:30).' } }];
if (parsed.ms <= Date.now()) return [{ json: { valid: false, chatId, errorMsg: '❌ Esa fecha y hora ya pasaron. Mandá una futura: DD/MM HH:MM.' } }];

// compliance + firma
const FIRMA_FALLBACK = '-- Consultora de Belleza Independiente Mary Kay --';
let cfg = {};
try { const c = (($('Sched: Leer Config').first() || {}).json) || {}; for (const h of Object.keys(c)) cfg[h.trim().toLowerCase()] = String(c[h] == null ? '' : c[h]).trim(); } catch (e) {}
const firmaLinea = cfg.firma || FIRMA_FALLBACK;
