const patrones = [/(\$|u\$s|us\$|ar\$|€|£)\s*\d/i, /\d\s*[.,]?\d*\s*(pesos?|ars|usd|u\$d|d[oó]lares?|euros?|mangos?|lucas?)\b/i, /\d+[.,]\d{3}/, /\d+\s*%\s*(off|desc|descuento)/i, /\b(ofertas?|promos?|promoci[oó]n(?:es)?|descuentos?|rebajas?|barat[oa]s?|econ[oó]mic[oa]s?|gratis|2x1|3x2|cuotas?|financiaci[oó]n(?:es)?|sin\s+inter[eé]s)\b/i, /\b(precios?|cuesta|vale|abon[aá]s?)\s*(?:es|son|de|desde|:)?\s*\$?\s*\d/i];
let pat = '';
for (const p of patrones) { const mm = copy.match(p); if (mm) { pat = mm[0]; break; } }
if (pat) {
  delete store['schedulePending_' + chatId];
  return [{ json: { valid: false, chatId, errorMsg: '⚠️ Postly detectó contenido prohibido: "' + pat + '". No podés programar precios ni promociones. Editá el texto y empezá de nuevo.' } }];
}

let caption = copy;
